import{_ as a,o as t,c as o,ag as s}from"./chunks/framework.DoUXNnsN.js";const u=JSON.parse('{"title":"Git工作流","description":"","frontmatter":{"title":"Git工作流","aliases":["Git Workflow","feature分支","Pull Request","PR","Merge Request","MR","提交信息规范","Conventional Commits","GitHub Flow","Git Flow","分支策略"],"tags":["工具与工程","Git"],"status":"ai-draft","sources":["https://www.conventionalcommits.org/zh-hans/v1.0.0/","https://docs.github.com/en/get-started/using-github/github-flow","https://git-scm.com/book/zh/v2/分布式-Git-向一个项目贡献","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":6},"headers":[],"relativePath":"50-工具与工程/Git/Git工作流.md","filePath":"50-工具与工程/Git/Git工作流.md"}'),n={name:"50-工具与工程/Git/Git工作流.md"};function i(l,e,d,c,r,p){return t(),o("div",null,[...e[0]||(e[0]=[s(`<blockquote><p>本篇是 <a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a> 入门路径的第 5 篇（系列最后一篇）。读完你应该能：说清一个功能从开分支到合并上线的完整流程；写出规范的提交信息；知道 PR/MR 是什么、评审时看什么；为小团队定下一套简单可行的约定。</p><p>本地部分（分支、<code>--no-ff</code> 合并、tag、按提交信息检索）在 Windows 11 + Git for Windows 2.54.0（Git Bash）里实际运行；<strong>Pull Request 是 Gitee/GitHub 网页上的功能，无法在本地仓库复现，下面的网页流程依据官方文档整理，未在本机验证</strong>。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p>Git 工作流是团队关于&quot;怎么用分支、怎么提交、怎么评审、怎么合并发布&quot;的一套<strong>约定</strong>：Git 本身不规定这些，但没有约定，多人协作很快会乱。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li><a href="/Encyclopedia/50-工具与工程/Git/Git分支与合并">Git分支与合并</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git远程仓库">Git远程仓库</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git冲突与撤销">Git冲突与撤销</a>。</li><li>了解团队开发的基本节奏，见 <a href="/Encyclopedia/50-工具与工程/软件开发流程">软件开发流程</a>。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>三个人同时往 <code>main</code> 直接提交会发生：</p><ol><li>半成品、有 bug 的代码进了主线，所有人被拖累。</li><li>没人评审，错误到了线上才发现。</li><li>提交说明全是&quot;修改&quot;&quot;update&quot;&quot;111&quot;，三个月后没人知道某次改动为什么发生。</li></ol><p>工作流的核心就是三条：<strong>主线永远可发布</strong>、<strong>每件事一个分支</strong>、<strong>合并前有人看过</strong>。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="常见分支策略" tabindex="-1">常见分支策略 <a class="header-anchor" href="#常见分支策略" aria-label="Permalink to &quot;常见分支策略&quot;">​</a></h3><table tabindex="0"><thead><tr><th>策略</th><th>做法</th><th>适合</th></tr></thead><tbody><tr><td>GitHub Flow（简化）</td><td>只有 <code>main</code> + 短命的功能分支；功能分支经 PR 评审后合入 main；main 随时可部署</td><td>小团队、持续发布、Web/内部系统</td></tr><tr><td>Git Flow</td><td><code>main</code>（发布）+ <code>develop</code>（集成）+ <code>feature/*</code> + <code>release/*</code> + <code>hotfix/*</code></td><td>有明确版本发布节奏、需维护多个版本的产品</td></tr><tr><td>Trunk-Based</td><td>几乎直接在主干上提交，配合功能开关和强自动化测试</td><td>自动化程度高的大团队</td></tr></tbody></table><p>内部业务系统（如 MES 的某个模块）团队 3~10 人，推荐从 <strong>GitHub Flow</strong> 起步：规则少，不容易乱。后面的例子都按它来。</p><h3 id="feature-分支流程" tabindex="-1">Feature 分支流程 <a class="header-anchor" href="#feature-分支流程" aria-label="Permalink to &quot;Feature 分支流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 从最新的 main 拉出分支  git switch main &amp;&amp; git pull &amp;&amp; git switch -c feature/导出CSV</span></span>
<span class="line"><span>2. 在分支上小步提交</span></span>
<span class="line"><span>3. 推送分支             git push -u origin feature/导出CSV</span></span>
<span class="line"><span>4. 在网页上发起 PR/MR，请同事评审</span></span>
<span class="line"><span>5. 评审通过 + 自动检查通过 -&gt; 合并进 main</span></span>
<span class="line"><span>6. 删除分支；必要时打 tag 发布</span></span></code></pre></div><p><strong>PR</strong>（Pull Request，GitHub/Gitee 的叫法）与 <strong>MR</strong>（Merge Request，GitLab 的叫法）是同一个概念：一个&quot;请求把我的分支合入主线&quot;的网页页面，上面可以看到改动对比、讨论、评审意见、自动检查结果。它不是 Git 命令，是托管平台的功能。</p><h3 id="分支命名" tabindex="-1">分支命名 <a class="header-anchor" href="#分支命名" aria-label="Permalink to &quot;分支命名&quot;">​</a></h3><p>用&quot;类型/简短描述&quot;，小写，用 <code>-</code> 连接，最好带上需求/工单号：</p><table tabindex="0"><thead><tr><th>前缀</th><th>用途</th><th>例子</th></tr></thead><tbody><tr><td><code>feature/</code></td><td>新功能</td><td><code>feature/export-csv</code></td></tr><tr><td><code>fix/</code> 或 <code>bugfix/</code></td><td>修 bug</td><td><code>fix/mes-1234-scan-crash</code></td></tr><tr><td><code>hotfix/</code></td><td>线上紧急修复</td><td><code>hotfix/login-500</code></td></tr><tr><td><code>docs/</code>、<code>refactor/</code></td><td>文档、重构</td><td><code>docs/api-readme</code></td></tr></tbody></table><p>名字里的 <code>/</code> 会被当作&quot;目录&quot;，在多数界面里自动分组。尽量用英文和数字，避免中文和空格，减少编码和命令行引号问题。</p><h3 id="提交信息规范" tabindex="-1">提交信息规范 <a class="header-anchor" href="#提交信息规范" aria-label="Permalink to &quot;提交信息规范&quot;">​</a></h3><p>好的提交信息让 <code>git log</code> 成为一份可读的&quot;变更日志&quot;。</p><p>基本约定：</p><ul><li><strong>第一行（标题）</strong>：不超过约 50 个字符（中文可放宽到 30 字内），说明&quot;做了什么&quot;，用祈使/陈述语气，不加句号。</li><li><strong>空一行</strong>，然后写正文（可选）：说明<strong>为什么</strong>这样改、有什么影响。&quot;做了什么&quot;代码里看得到，&quot;为什么&quot;只有你知道。</li><li>一个提交只做一件事，别把三件无关的事塞进一个提交。</li></ul><p>很多团队采用 <strong>Conventional Commits</strong> 规范，格式为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;类型&gt;[可选范围]: &lt;描述&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[可选正文]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[可选脚注]</span></span></code></pre></div><p>标准类型（来自官方规范 <a href="https://www.conventionalcommits.org/zh-hans/v1.0.0/" target="_blank" rel="noreferrer">https://www.conventionalcommits.org/zh-hans/v1.0.0/</a>）：<code>feat</code> 新功能、<code>fix</code> 修复 bug；常见其它类型有 <code>docs</code>、<code>style</code>、<code>refactor</code>、<code>perf</code>、<code>test</code>、<code>build</code>、<code>ci</code>、<code>chore</code>。破坏性变更在类型后加 <code>!</code>（如 <code>feat(api)!: ...</code>），或在脚注写 <code>BREAKING CHANGE: 说明</code>。规范里 <code>fix</code> 对应语义化版本的 PATCH、<code>feat</code> 对应 MINOR、破坏性变更对应 MAJOR。</p><p>对比：</p><table tabindex="0"><thead><tr><th>差</th><th>好</th></tr></thead><tbody><tr><td><code>update</code></td><td><code>fix(scan): 修复条码末尾空格导致过站失败</code></td></tr><tr><td><code>111</code></td><td><code>feat(export): 新增工单CSV导出</code></td></tr><tr><td><code>修改了一些东西</code></td><td><code>refactor(report): 抽出报表查询公共方法</code></td></tr></tbody></table><h2 id="逐步例子" tabindex="-1">逐步例子 <a class="header-anchor" href="#逐步例子" aria-label="Permalink to &quot;逐步例子&quot;">​</a></h2><p>场景：为小系统添加&quot;导出 CSV&quot;功能。以下为本地实际运行（<code>main</code> 上已有 <code>init</code>、<code>add b.txt</code> 两个提交）。</p><h3 id="第-1-步-开-feature-分支并小步提交" tabindex="-1">第 1 步：开 feature 分支并小步提交 <a class="header-anchor" href="#第-1-步-开-feature-分支并小步提交" aria-label="Permalink to &quot;第 1 步：开 feature 分支并小步提交&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git switch -c feature/export-csv</span></span>
<span class="line"><span>$ echo e1 &gt; export.py &amp;&amp; git add . &amp;&amp; git commit -m &quot;feat(export): add CSV export&quot;</span></span>
<span class="line"><span>$ echo e2 &gt;&gt; export.py &amp;&amp; git commit -am &quot;fix(export): escape commas in CSV&quot;</span></span></code></pre></div><p>两个提交各做一件事，标题都符合 Conventional Commits。实际项目里这里还会 <code>git push -u origin feature/export-csv</code> 并发起 PR（见下文）。</p><h3 id="第-2-步-合并回-main-保留分支轮廓-no-ff" tabindex="-1">第 2 步：合并回 main，保留分支轮廓（--no-ff） <a class="header-anchor" href="#第-2-步-合并回-main-保留分支轮廓-no-ff" aria-label="Permalink to &quot;第 2 步：合并回 main，保留分支轮廓（--no-ff）&quot;">​</a></h3><p>评审通过后合并。<code>--no-ff</code> 的意思是&quot;即使可以快进，也生成一个合并提交&quot;，这样历史图上能清楚看到这个功能分支存在过：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git switch main</span></span>
<span class="line"><span>$ git merge --no-ff feature/export-csv -m &quot;Merge branch &#39;feature/export-csv&#39;&quot;</span></span>
<span class="line"><span>Merge made by the &#39;ort&#39; strategy.</span></span>
<span class="line"><span> export.py | 2 ++</span></span>
<span class="line"><span> 1 file changed, 2 insertions(+)</span></span>
<span class="line"><span> create mode 100644 export.py</span></span>
<span class="line"><span>$ git log --oneline --graph</span></span>
<span class="line"><span>*   07fbf50 Merge branch &#39;feature/export-csv&#39;</span></span>
<span class="line"><span>|\\</span></span>
<span class="line"><span>| * 316d3ef fix(export): escape commas in CSV</span></span>
<span class="line"><span>| * de1c7c5 feat(export): add CSV export</span></span>
<span class="line"><span>|/</span></span>
<span class="line"><span>* e199bf9 add b.txt</span></span>
<span class="line"><span>* 9f30f3d init</span></span></code></pre></div><p>在 Gitee/GitHub 的 PR 页面点&quot;合并&quot;时，平台通常提供三种方式：<strong>Merge commit</strong>（相当于 <code>--no-ff</code>）、<strong>Squash and merge</strong>（把分支所有提交压成一个再合入，历史最干净，但分支内的小提交消失）、<strong>Rebase and merge</strong>（逐个重放，线性历史）。团队要统一选一种。</p><h3 id="第-3-步-清理分支、打-tag-发布" tabindex="-1">第 3 步：清理分支、打 tag 发布 <a class="header-anchor" href="#第-3-步-清理分支、打-tag-发布" aria-label="Permalink to &quot;第 3 步：清理分支、打 tag 发布&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git branch -d feature/export-csv</span></span>
<span class="line"><span>Deleted branch feature/export-csv (was 316d3ef).</span></span>
<span class="line"><span>$ git tag -a v1.0.0 -m &quot;release 1.0.0&quot;</span></span>
<span class="line"><span>$ git tag</span></span>
<span class="line"><span>v1.0.0</span></span></code></pre></div><p><strong>tag</strong>（标签）是给某个提交贴一个固定名字，用来标记发布版本（如 <code>v1.0.0</code>）。和分支不同，tag 不会移动。带 <code>-a</code> 的是附注标签，包含作者、日期和说明。推送 tag 需要单独执行 <code>git push origin v1.0.0</code>（或 <code>git push --tags</code>）。版本号常用语义化版本 <code>主.次.补丁</code>。</p><h3 id="第-4-步-用规范的提交信息检索历史" tabindex="-1">第 4 步：用规范的提交信息检索历史 <a class="header-anchor" href="#第-4-步-用规范的提交信息检索历史" aria-label="Permalink to &quot;第 4 步：用规范的提交信息检索历史&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git log --oneline --grep=&quot;^feat&quot;</span></span>
<span class="line"><span>de1c7c5 feat(export): add CSV export</span></span>
<span class="line"><span>$ git log --pretty=format:&quot;%h %an %s&quot; -3</span></span>
<span class="line"><span>07fbf50 Lab User Merge branch &#39;feature/export-csv&#39;</span></span>
<span class="line"><span>316d3ef Lab User fix(export): escape commas in CSV</span></span>
<span class="line"><span>de1c7c5 Lab User feat(export): add CSV export</span></span></code></pre></div><p><code>--grep</code> 按提交信息搜索，<code>--pretty=format:</code> 自定义输出（<code>%h</code> 短哈希、<code>%an</code> 作者、<code>%s</code> 标题）。规范的信息还能被工具自动生成变更日志和版本号。</p><p>追责或理解某行代码为什么这么写时，用 <code>git blame</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git blame -L1,1 a.txt</span></span>
<span class="line"><span>^9f30f3d (Lab User 2026-10-21 20:05:46 +0800 1) a</span></span></code></pre></div><p>输出格式：该行最后一次改动的提交哈希、作者、时间、行号、内容（行首 <code>^</code> 表示它来自仓库的第一个提交）。</p><h2 id="pull-request-merge-request-流程-网页-未在本机验证" tabindex="-1">Pull Request / Merge Request 流程（网页，未在本机验证） <a class="header-anchor" href="#pull-request-merge-request-流程-网页-未在本机验证" aria-label="Permalink to &quot;Pull Request / Merge Request 流程（网页，未在本机验证）&quot;">​</a></h2><ol><li>把 feature 分支 push 到远程。</li><li>在 Gitee/GitHub 上点击&quot;新建 Pull Request&quot;，选择&quot;从 feature/xxx 合入 main&quot;。</li><li>填写标题和说明，说明模板建议包含：<strong>改了什么、为什么改、怎么测的、有无风险（比如要不要改数据库）</strong>。关联需求/工单号。</li><li>指定评审人（reviewer）。自动化检查（构建、测试）会在 PR 上跑，见 <a href="/Encyclopedia/50-工具与工程/CI-CD">CI-CD</a>。</li><li>评审人逐行留言；你继续在<strong>同一分支</strong>上提交修改，PR 自动更新。</li><li>通过后由有权限的人合并。合并后删除远程分支。</li></ol><h3 id="评审-code-review-看什么" tabindex="-1">评审（Code Review）看什么 <a class="header-anchor" href="#评审-code-review-看什么" aria-label="Permalink to &quot;评审（Code Review）看什么&quot;">​</a></h3><ul><li>逻辑对不对，边界情况（空值、重复扫码、并发）有没有考虑。</li><li>有没有把密码、令牌、连接串提交进来（见 <a href="/Encyclopedia/50-工具与工程/Git/Git远程仓库">Git远程仓库</a>）。</li><li>有没有数据库变更脚本，是否可回滚。</li><li>命名、结构是否符合团队规范，见 <a href="/Encyclopedia/50-工具与工程/代码规范与重构">代码规范与重构</a>。</li><li>PR 是否太大：超过几百行就难以认真评审，建议拆小。</li></ul><h2 id="团队约定清单-可直接抄" tabindex="-1">团队约定清单（可直接抄） <a class="header-anchor" href="#团队约定清单-可直接抄" aria-label="Permalink to &quot;团队约定清单（可直接抄）&quot;">​</a></h2><ol><li><code>main</code> 永远可发布；<strong>保护 main</strong>：在平台设置里禁止直接 push，必须经 PR，且至少 1 人评审通过、检查通过。</li><li>分支从最新的 <code>main</code> 拉出，命名 <code>类型/描述</code>；寿命短（几天内合并），长期分支会带来大量冲突。</li><li>提交信息用 Conventional Commits，一个提交只做一件事。</li><li>合并方式全队统一（推荐 Squash 或 Merge commit 二选一）。</li><li>已推送的共享分支不 rebase、不强推；个人分支强推用 <code>--force-with-lease</code>。</li><li>密钥/配置不入库，<code>.gitignore</code> 随项目一起维护。</li><li>版本发布打 tag，格式 <code>vX.Y.Z</code>。</li><li>每天开始工作先 <code>git pull</code>（或 <code>git pull --rebase</code>），减少冲突。</li></ol><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ol><li>在空文件夹 <code>flow-lab</code> 里 <code>git init -b main</code>，设置本仓库 user，提交 <code>init</code>。</li><li><code>git switch -c feature/hello</code>，提交 <code>feat(hello): add hello.txt</code>；再提交 <code>fix(hello): fix typo</code>。</li><li><code>git switch main &amp;&amp; git merge --no-ff feature/hello -m &quot;Merge feature/hello&quot;</code>，运行 <code>git log --oneline --graph</code> 应看到分叉汇合图。</li><li><code>git branch -d feature/hello</code>，<code>git tag -a v0.1.0 -m &quot;first&quot;</code>，<code>git tag</code> 应显示 <code>v0.1.0</code>。</li><li><code>git log --oneline --grep=&quot;^fix&quot;</code> 应只有一条。</li><li>进阶（需要账号）：在 Gitee 上建一个测试仓库，把上面的 feature 分支 push 上去，在网页发起 PR 并自己合并，体会流程。</li></ol><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><ul><li><strong>PR 里混进了无关改动</strong>：分支名乱用，或者从旧 main 拉的分支。开始前先 <code>git pull</code>，一个分支只做一件事。</li><li><strong>长期分支落后太多，合并冲突爆炸</strong>：定期把 main 合并/变基到自己的分支，或拆小需求。</li><li><strong>直接在 main 上改了才发现</strong>：还没提交就 <code>git switch -c feature/xxx</code>，改动会跟着过去；已提交没推送的，建新分支后把 main <code>reset</code> 回 origin/main（先弄清楚再动手，见 <a href="/Encyclopedia/50-工具与工程/Git/Git冲突与撤销">Git冲突与撤销</a>）。</li><li><strong>合并方式不统一</strong>：有人 squash 有人 merge，历史风格混杂，约定后写进团队文档。</li><li><strong>tag 没推送</strong>：<code>git push</code> 默认不推 tag，要单独推。</li><li><strong>提交信息中文乱码</strong>：多发生在旧环境，统一使用 UTF-8；Git for Windows 默认已是 UTF-8。</li></ul><h2 id="业务视角与技术视角" tabindex="-1">业务视角与技术视角 <a class="header-anchor" href="#业务视角与技术视角" aria-label="Permalink to &quot;业务视角与技术视角&quot;">​</a></h2><ul><li><strong>业务视角</strong>：MES/WMS 这类工厂系统，改动直接影响产线（卡单、条码打错、库存账不对）。所以更要求&quot;主线可发布、改动可追溯、出问题能快速回滚&quot;：每次上线打 tag，出问题用 tag 找到上个稳定版本；提交信息关联工单号，方便向业务方解释&quot;这次为什么改&quot;。</li><li><strong>技术视角</strong>：分支保护 + PR 评审 + CI 自动构建测试（见 <a href="/Encyclopedia/50-工具与工程/CI-CD">CI-CD</a>、<a href="/Encyclopedia/50-工具与工程/软件测试">软件测试</a>）是组合拳；数据库脚本也要纳入 Git 管理，和代码一起评审。公司具体的分支规则以你们团队实际约定为准。</li></ul><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><p><strong>1.</strong> 为什么要保护 <code>main</code>？ 答：保证主线可发布，所有改动必经评审与自动检查，防止半成品和错误直接进入主线。</p><p><strong>2.</strong> <code>--no-ff</code> 有什么用？ 答：强制生成合并提交，历史上保留&quot;这个功能分支存在过&quot;的痕迹，便于整体回退一个功能（对合并提交做 <code>revert -m 1</code>）。</p><p><strong>3.</strong> 判断这两条提交信息的好坏：<code>fix bug</code> 和 <code>fix(scan): 条码含空格时过站失败</code>。 答：前者没有说明什么 bug、哪个模块；后者类型、范围、现象都清楚。</p><p><strong>4.</strong> tag 和 branch 的区别？ 答：branch 会随提交向前移动；tag 固定指向一个提交，用于标记版本。</p><p><strong>5.</strong> 评审时发现 PR 有 1500 行改动，应该怎么办？ 答：要求作者拆成几个小 PR，分别评审；大 PR 很难看仔细，容易漏问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>工作流三原则：主线可发布、每件事一个分支、合并前有评审。</li><li>小团队从 GitHub Flow 起步：<code>main</code> + 短命 <code>feature/*</code> + PR。</li><li>提交信息写清&quot;做了什么、为什么&quot;；Conventional Commits 让历史可读、可检索、可自动化。</li><li>版本用 tag 标记；保护 main；已共享的历史不改写。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git分支与合并">Git分支与合并</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git远程仓库">Git远程仓库</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git冲突与撤销">Git冲突与撤销</a>、<a href="/Encyclopedia/50-工具与工程/CI-CD">CI-CD</a>、<a href="/Encyclopedia/50-工具与工程/软件开发流程">软件开发流程</a>、<a href="/Encyclopedia/50-工具与工程/代码规范与重构">代码规范与重构</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>Conventional Commits 1.0.0 中文版：<a href="https://www.conventionalcommits.org/zh-hans/v1.0.0/" target="_blank" rel="noreferrer">https://www.conventionalcommits.org/zh-hans/v1.0.0/</a></li><li>GitHub Flow：<a href="https://docs.github.com/en/get-started/using-github/github-flow" target="_blank" rel="noreferrer">https://docs.github.com/en/get-started/using-github/github-flow</a></li><li>Pro Git：向一个项目贡献：<a href="https://git-scm.com/book/zh/v2/%E5%88%86%E5%B8%83%E5%BC%8F-Git-%E5%90%91%E4%B8%80%E4%B8%AA%E9%A1%B9%E7%9B%AE%E8%B4%A1%E7%8C%AE" target="_blank" rel="noreferrer">https://git-scm.com/book/zh/v2/分布式-Git-向一个项目贡献</a></li></ul>`,71)])])}const g=a(n,[["render",i]]);export{u as __pageData,g as default};
